\section{Introduction}

\subsection{The question}
For a monic cubic $f\in\mathbb{Z}[x]$ and a prime $p\nmid\disc(f)$, the reduction
$f\bmod p$ factors over $\F_p$ in one of three ways: into three linear factors (type
$111$), a linear times an irreducible quadratic (type $12$), or not at all (type $3$). The
type can be read off from the number of roots of $f$ in $\F_p$, which is $3$, $1$ or $0$
respectively. We call the map $p\mapsto T_f(p)\in\{111,12,3\}$ the \emph{dial} of $f$.

If $L_f$ is the splitting field of $f$ and $\Gal(L_f/\Q)\cong S_3$, then $T_f(p)$ is the
cycle type of the Frobenius class $\mathrm{Frob}_p\subset S_3$. The Chebotarev density
theorem says that Frobenius classes are equidistributed with respect to the counting
measure on the group. So the dial behaves like a random variable with law
\[
\Pr[T=111]=\tfrac16,\qquad \Pr[T=12]=\tfrac12,\qquad \Pr[T=3]=\tfrac13 .
\]
Now take two cubics $f$ and $g$ and read both dials at the \emph{same} prime.
\begin{quote}
\emph{How much does the reading of one dial reveal about the reading of the other?}
\end{quote}
We measure this by Shannon's mutual information $I(T_f;T_g)$ in bits.

\subsection{Answer in one line}
\[
I(T_f;T_g)=
\begin{cases}
0 & \text{if } \Q(\sqrt{\disc f})\neq\Q(\sqrt{\disc g}),\\
1 & \text{if } \Q(\sqrt{\disc f})=\Q(\sqrt{\disc g}) \text{ and } L_f\neq L_g.
\end{cases}
\]
The single shared bit in the second case is the common value of the Legendre symbol
$\left(\frac{\Delta}{p}\right)$, where $\Delta$ is either discriminant. Nothing else is
shared.

\subsection{Motivation and context}
This work belongs to a series of experiments that treat arithmetic statistics as
communication channels. A number field is a ``transmitter'', a prime is a ``channel
use'', and the splitting type is the received ``symbol''. An earlier installment showed
that a quadratic character carries exactly one bit. The present installment asks whether
\emph{two} transmitters interfere with each other.

Across $452$ experiments to date, the headline measurements for this question were a
plug-in estimate $I(\text{type}_1;\text{type}_2)=0.000437$ bits for primes (null-model
$z=-0.81$), and $I(\text{pair}_1;\text{pair}_2)=0.001424$ bits for semiprimes ($z=+2.79$).
These are statistics, not theorems. The purpose of this paper is to replace them with
exact values and to explain the one situation in which cross-talk does occur. The verdict
is: \textbf{the dials are independent}.

\subsection{Modelling assumptions}
\textbf{(A) Galois structure of the compositum.} Let $L_f,L_g$ be $S_3$-extensions of $\Q$
with quadratic subfields $K_f=\Q(\sqrt{\disc f})$ and $K_g=\Q(\sqrt{\disc g})$. The field
$L_f\cap L_g$ is Galois over $\Q$, so it corresponds to a normal subgroup of $S_3$. Hence
it is $\Q$, the quadratic resolvent, or the whole field. Consequently, if $K_f\neq K_g$
then $\Gal(L_fL_g/\Q)\cong S_3\times S_3$. If $K_f=K_g$ but $L_f\neq L_g$, then
\[
\Gal(L_fL_g/\Q)\cong S_3\times_{C_2}S_3:=\{(\sigma,\tau)\in S_3\times S_3:\sgn\sigma=\sgn\tau\}.
\]
Coprime discriminants are a convenient sufficient condition in practice for
$K_f\neq K_g$, but the condition that actually matters is that the quadratic resolvents
are distinct.

\textbf{(B) Chebotarev.} For primes unramified in $L_fL_g$, the Frobenius class in the
compositum group is equidistributed. For a semiprime $N=pq$, we model the two Frobenius
elements as independent uniform draws, so the sample space is the square of the
compositum group.

All results below are exact statements about uniform probability on finite sets. The
arithmetic enters only through the choice of sample space.

\section{Entropy on finite uniform sample spaces}

Throughout, $S$ is a nonempty finite set with the uniform probability measure, and a
\emph{read-out} is any function $g:S\to B$. All logarithms are to base $2$.

\begin{definition}[Uniform entropy]
For $x\in S$ let $S_g(x)=\{y\in S: g(y)=g(x)\}$. The entropy of $g$ on $S$ is
\[
H_S(g)=\frac1{|S|}\sum_{x\in S}\log_2\frac{|S|}{|S_g(x)|}
=\sum_b \frac{n_b}{|S|}\log_2\frac{|S|}{n_b},\qquad n_b=\#g^{-1}(b).
\]
It depends only on the partition of $S$ into fibres of $g$. In particular, a constant
read-out has entropy $0$.
\end{definition}

\begin{definition}[Conditional entropy and mutual information]
For read-outs $g:S\to B$ and $k:S\to C$,
\[
H_S(g\mid k)=\sum_{c\in k(S)}\frac{\#k^{-1}(c)}{|S|}\,H_{k^{-1}(c)}(g),\qquad
I_S(g;k)=H_S(g)-H_S(g\mid k).
\]
\end{definition}

We use three standard facts. The chain rule $H_S(g\mid k)=H_S(g,k)-H_S(k)$. Symmetry,
$I_S(g;k)=I_S(k;g)$. And the Gibbs inequality $I_S(g;k)\ge 0$.

\begin{definition}[Count independence]
Read-outs $g,k$ are \emph{count-independent} on $S$ if for all values $b,c$
\[
|S|\cdot\#\{x\in S: g(x)=b,\ k(x)=c\}=\#\{x\in S:g(x)=b\}\cdot\#\{x\in S:k(x)=c\}.
\]
\end{definition}

\section{General results}

\subsection{Independence and zero information}

\begin{theorem}[Independence implies zero mutual information]\label{thm:indep}
If $S$ is nonempty and $g,k$ are count-independent on $S$, then $I_S(g;k)=0$.
\end{theorem}
\begin{proof}[Proof sketch]
Fix a value $c$ of $k$ and let $S_c=k^{-1}(c)$. For $a\in S_c$, count independence gives
$\#\{x\in S_c: g(x)=g(a)\}=|S_g(a)|\,|S_c|/|S|$. Taking logarithms and summing over $S_c$
gives
\[
\frac{|S_c|}{|S|}H_{S_c}(g)=\frac{|S_c|}{|S|}\log_2|S|-\frac1{|S|}\sum_{a\in S_c}\log_2|S_g(a)|.
\]
Summing over $c$, and using that the $S_c$ partition $S$, yields $H_S(g\mid k)=H_S(g)$.
\end{proof}

\begin{theorem}[Product sample spaces are count-independent]\label{thm:prod}
For finite $S,T$ and read-outs $g:S\to D$, $k:T\to E$, the read-outs $(x,y)\mapsto g(x)$
and $(x,y)\mapsto k(y)$ are count-independent on $S\times T$.
\end{theorem}
\begin{proof}
The joint fibre is $g^{-1}(b)\times k^{-1}(c)$ and the marginal fibres are
$g^{-1}(b)\times T$ and $S\times k^{-1}(c)$, so
$|S||T|\cdot|g^{-1}(b)||k^{-1}(c)|=(|g^{-1}(b)||T|)(|S||k^{-1}(c)|)$.
\end{proof}

\begin{corollary}[Linearly disjoint dials share nothing]\label{cor:disjoint}
If $S,T$ are nonempty, then $I_{S\times T}(g\circ\pr_1;k\circ\pr_2)=0$. In particular,
for finite groups $G,H$ and arbitrary read-outs $T_1$ on $G$ and $T_2$ on $H$, we have
$I_{G\times H}(T_1;T_2)=0$.
\end{corollary}

\subsection{Additivity over independent blocks}

\begin{theorem}[Additivity of entropy]\label{thm:addH}
For nonempty finite $S,T$,
$H_{S\times T}\bigl((x,y)\mapsto(g(x),k(y))\bigr)=H_S(g)+H_T(k)$.
\end{theorem}
\begin{proof}[Proof sketch]
The fibre through $(x,y)$ is $S_g(x)\times T_k(y)$, so its logarithmic size splits.
Summing over $S\times T$ gives the claim.
\end{proof}

\begin{corollary}[Marginals]\label{cor:marg}
$H_{S\times T}(g\circ\pr_1)=H_S(g)$.
\end{corollary}

\begin{theorem}[Additivity of mutual information]\label{thm:addI}
For nonempty $S,T$ and read-outs $g_1,k_1$ on $S$ and $g_2,k_2$ on $T$,
\[
I_{S\times T}\bigl((g_1,g_2);(k_1,k_2)\bigr)=I_S(g_1;k_1)+I_T(g_2;k_2).
\]
\end{theorem}
\begin{proof}[Proof sketch]
Write $I=H(g)+H(k)-H(g,k)$ and split each entropy by Theorem~\ref{thm:addH}. The joint
read-out $((g_1,g_2),(k_1,k_2))$ induces the same partition as
$((g_1,k_1),(g_2,k_2))$.
\end{proof}

\subsection{Data processing}

\begin{theorem}[Conditioning on less cannot reduce uncertainty]\label{thm:cond}
For read-outs $k:S\to B$, $g:S\to C$ and any map $h:C\to D$,
$H_S(k\mid g)\le H_S(k\mid h\circ g)$.
\end{theorem}
\begin{proof}[Proof sketch]
On each fibre $F$ of $h\circ g$, the Gibbs inequality gives $H_F(k,g)-H_F(g)\le H_F(k)$.
Multiply by $|F|/|S|$ and sum over fibres. The left side becomes $H_S(k\mid g)$ by the
chain rule, since $g$ determines $h\circ g$; the right side is $H_S(k\mid h\circ g)$.
\end{proof}

\begin{corollary}[Data processing inequality]\label{cor:dpi}
$I_S(k;h\circ g)\le I_S(k;g)$ and $I_S(h\circ g;k)\le I_S(g;k)$.
\end{corollary}

\subsection{Fibre products over a two-element quotient}

\begin{definition}
For finite groups $G,H,C$ and homomorphisms $\chi_1:G\to C$, $\chi_2:H\to C$, the
\emph{fibre product} is $G\times_C H=\{(a,b)\in G\times H:\chi_1(a)=\chi_2(b)\}$. If
$\chi_1,\chi_2$ cut out the same subfield $L_1\cap L_2$, this is the Galois group of the
compositum $L_1L_2$.
\end{definition}

\begin{lemma}[Fibres are products]\label{lem:fib}
For every $c\in C$,
$\{(a,b)\in G\times_C H:\chi_1(a)=c\}=\chi_1^{-1}(c)\times\chi_2^{-1}(c)$.
\end{lemma}

\begin{lemma}[Balance]\label{lem:bal}
If $\chi_1,\chi_2$ are surjective and $|C|=2$, then for each $c\in C$ exactly half of
$G\times_C H$ satisfies $\chi_1(a)=c$.
\end{lemma}
\begin{proof}
All fibres of a surjective homomorphism have the size of its kernel. By
Lemma~\ref{lem:fib}, both fibres of the common character therefore have
$|\ker\chi_1|\,|\ker\chi_2|$ elements.
\end{proof}

\begin{theorem}[A shared quadratic quotient forces at least one bit]\label{thm:onebit}
Let $\chi_1:G\to C$ and $\chi_2:H\to C$ be surjective onto a group of order $2$. Let
$T_1:G\to B$ and $T_2:H\to B'$ be read-outs with $\chi_1=f_1\circ T_1$ and
$\chi_2=f_2\circ T_2$ for some maps $f_1,f_2$. Then $I_{G\times_C H}(T_1;T_2)\ge 1$.
\end{theorem}
\begin{proof}[Proof sketch]
On $S=G\times_C H$, the read-outs $f_1\circ T_1=\chi_1$ and $f_2\circ T_2=\chi_2$ are
equal, and by Lemma~\ref{lem:bal} their common value is a fair coin. Hence
$I_S(\chi_1;\chi_2)=1$. By Corollary~\ref{cor:dpi},
$1=I_S(f_1\circ T_1;f_2\circ T_2)\le I_S(T_1;f_2\circ T_2)\le I_S(T_1;T_2)$.
\end{proof}

\section{The two cubic dials}

Let $T:S_3\to\{111,12,3\}$ be the cycle type. Then $T^{-1}(111)=\{e\}$, $T^{-1}(12)$ is
the set of three transpositions, and $T^{-1}(3)$ is the set of two $3$-cycles. Moreover
$\sgn\sigma=-1$ if and only if $T(\sigma)=12$.

\begin{proposition}\label{prop:one}
$H_{S_3}(T)=\tfrac23+\tfrac12\log_2 3\approx 1.4591$ bits.
\end{proposition}
\begin{proof}
$\tfrac16\log_2 6+\tfrac12\log_2 2+\tfrac13\log_2 3=\tfrac16(1+\log_2 3)+\tfrac12+\tfrac13\log_2 3$.
\end{proof}

\begin{theorem}[The dials are independent]\label{thm:verdict}
On $S_3\times S_3$, with $T_i$ the type of the $i$-th coordinate,
\[
I(T_1;T_2)=0,\qquad H(T_1\mid T_2)=H(T_1)=\tfrac23+\tfrac12\log_2 3,\qquad
H(T_1,T_2)=\tfrac43+\log_2 3\approx 2.9183.
\]
\end{theorem}
\begin{proof}
The first equality is Corollary~\ref{cor:disjoint}. The second follows from
Corollary~\ref{cor:marg} and Proposition~\ref{prop:one}. The third is
Theorem~\ref{thm:addH}.
\end{proof}

The joint count table on the $36$ elements of $S_3\times S_3$ is the outer product of
$(1,3,2)$ with itself:
\begin{center}
\begin{tabular}{cccc}\toprule
$T_1\backslash T_2$ & $111$ & $12$ & $3$\\\midrule
$111$ & 1 & 3 & 2\\ $12$ & 3 & 9 & 6\\ $3$ & 2 & 6 & 4\\\bottomrule
\end{tabular}
\end{center}

\begin{proposition}\label{prop:table}
$|S_3\times_{C_2}S_3|=18$, and the joint count table of $(T_1,T_2)$ is
\begin{center}
\begin{tabular}{cccc}\toprule
$T_1\backslash T_2$ & $111$ & $12$ & $3$\\\midrule
$111$ & 1 & 0 & 2\\ $12$ & 0 & 9 & 0\\ $3$ & 2 & 0 & 4\\\bottomrule
\end{tabular}
\end{center}
\end{proposition}
\begin{proof}
The even pairs form $A_3\times A_3$ ($9$ elements, types in proportions $1:2:2:4$). The
odd pairs are the $9$ pairs of transpositions.
\end{proof}

\begin{proposition}[Marginals are unchanged]\label{prop:marg}
On $S_3\times_{C_2}S_3$ the law of $T_1$ is $(3,9,6)/18$, so
$H(T_1)=\tfrac23+\tfrac12\log_2 3$.
\end{proposition}

\begin{proposition}\label{prop:cond}
On $S_3\times_{C_2}S_3$, $H(T_1\mid T_2)=\tfrac12\log_2 3-\tfrac13$.
\end{proposition}
\begin{proof}
On the fibres $T_2=111$ (counts $1,2$) and $T_2=3$ (counts $2,4$), $T_1$ has entropy
$\log_2 3-\tfrac23$. On the fibre $T_2=12$, $T_1$ is constant. The weights are $3/18$,
$6/18$ and $9/18$, so $H(T_1\mid T_2)=\tfrac12(\log_2 3-\tfrac23)$.
\end{proof}

\begin{theorem}[Cross-talk is exactly one bit]\label{thm:shared}
On $S_3\times_{C_2}S_3$, $I(T_1;T_2)=1$.
\end{theorem}
\begin{proof}
$(\tfrac23+\tfrac12\log_2 3)-(\tfrac12\log_2 3-\tfrac13)=1$.
\end{proof}

\begin{remark}[Structural explanation]
On the odd half both dials read $12$. On the even half the sample space is the product
$A_3\times A_3$, so by Corollary~\ref{cor:disjoint} the dials are independent there. The
mutual information is therefore exactly the entropy of the fair sign coin.
\end{remark}

\begin{theorem}[Sharpness]
Theorem~\ref{thm:onebit} applies with $\chi_1=\chi_2=\sgn$, because the type determines
the sign. It gives $I(T_1;T_2)\ge1$, and Theorem~\ref{thm:shared} shows that equality
holds.
\end{theorem}

\begin{proposition}[Genuine dependence]
On $S_3\times_{C_2}S_3$, the read-outs $T_1,T_2$ are not count-independent: the cell
$(12,111)$ has count $0$, while $9\cdot 3/18\neq 0$.
\end{proposition}

\begin{theorem}[Dichotomy]
For two $S_3$ cubics with distinct splitting fields, under (A) and (B),
$I(T_f;T_g)=0$ if the quadratic resolvents differ and $I(T_f;T_g)=1$ if they coincide.
\end{theorem}

\begin{theorem}[Semiprime cross-talk]\label{thm:semi}
For $N=pq$ with pair read-outs:
\begin{enumerate}
\item on $(S_3\times S_3)^2$, $I(\mathrm{pair}_1;\mathrm{pair}_2)=0$;
\item on $(S_3\times_{C_2}S_3)^2$, $I(\mathrm{pair}_1;\mathrm{pair}_2)=2$;
\item in both cases $H(\mathrm{pair}_i)=\tfrac43+\log_2 3$.
\end{enumerate}
\end{theorem}
\begin{proof}
Parts 1 and 2 follow from Theorem~\ref{thm:addI} with Theorems~\ref{thm:verdict}
and~\ref{thm:shared}. Part 3 follows from Theorem~\ref{thm:addH} with
Propositions~\ref{prop:one} and~\ref{prop:marg}.
\end{proof}

\section{Algorithms}

\textbf{Exact cross-talk from a group.} Given a listed finite group
$\mathcal G\subseteq G\times H$ and read-outs $T_1,T_2$: build the joint count table
$n_{bc}$ with margins $n_{b\cdot}$, $n_{\cdot c}$, and return
$\sum_{n_{bc}>0}\frac{n_{bc}}{N}\log_2\frac{Nn_{bc}}{n_{b\cdot}n_{\cdot c}}$, where
$N=|\mathcal G|$. The cost is $O(|\mathcal G|)$. Count independence can be tested exactly
in integer arithmetic.

\textbf{Empirical dial experiment.} For each prime $5\le p<X$ not dividing either
discriminant, count the roots of $f$ and $g$ in $\F_p$ and map $3\mapsto111$,
$1\mapsto12$, $0\mapsto3$. Tabulate, compute the plug-in mutual information, and compare
with the first-order bias $(r-1)(c-1)/(2n\ln2)$ and with a permutation null.

